mapper.select:
SELECT api_id, name, revision, kind FROM (
    SELECT id AS api_id, name, dubbo_connection_revision AS revision, 'DRAFT' AS kind
    FROM catalog_api_draft WHERE environment_id=#{environmentId} AND dubbo_connection_id = #{connectionId}
    UNION ALL
    SELECT r.api_id, r.name, r.dubbo_connection_revision AS revision,
           CASE WHEN s.live_release_id = r.id THEN 'LIVE' ELSE 'PENDING' END AS kind
    FROM publication_release r JOIN publication_state s
      ON (s.live_release_id = r.id OR s.pending_release_id = r.id)
    WHERE r.environment_id=#{environmentId} AND s.environment_id=#{environmentId} AND r.dubbo_connection_id = #{connectionId}
) usages ORDER BY api_id, kind, revision
